"""Fail if a translatable string of the app has no translation in one of the shipped languages.

Usage: python check_translations.py <generated main.pot> <locale dir>
The .pot is generated by ``bench generate-pot-file --app rappen`` in CI, so it contains every string that
Frappe extracts from Python, JavaScript, Jinja templates and doctype JSON. Every one of them needs a
translation in de, fr and it.

Generic words (e.g. «Date» on a print format) carry the context «Rappen» (``_("Date", context="Rappen")``),
so that Rappen's translation does not replace Frappe's for the whole user interface.
"""

import ast
import sys
from pathlib import Path

LANGUAGES = ("de", "fr", "it")


def read_catalog(path: Path) -> dict[tuple[str, str], str]:
	"""(msgctxt, msgid) to msgstr, for .po or .pot files without plural forms."""
	entries: dict[tuple[str, str], str] = {}
	current = {"msgctxt": "", "msgid": "", "msgstr": ""}
	key = None

	def flush():
		if current["msgid"]:
			entries[(current["msgctxt"], current["msgid"])] = current["msgstr"]

	for line in path.read_text(encoding="utf-8").splitlines():
		line = line.strip()
		if not line or line.startswith("#"):
			continue
		keyword = next((k for k in ("msgctxt", "msgid", "msgstr") if line.startswith(k + " ")), None)
		if keyword:
			# A new entry starts with msgctxt, or with msgid when the previous entry is complete
			if keyword == "msgctxt" or (keyword == "msgid" and key == "msgstr"):
				flush()
				current = {"msgctxt": "", "msgid": "", "msgstr": ""}
			key = keyword
			current[key] = ast.literal_eval(line[len(keyword) + 1 :])
		elif line.startswith('"') and key:
			current[key] += ast.literal_eval(line)
	flush()
	return entries


def main() -> int:
	pot, locale = Path(sys.argv[1]), Path(sys.argv[2])
	wanted = sorted(read_catalog(pot))
	missing = 0
	for language in LANGUAGES:
		translated = read_catalog(locale / f"{language}.po")
		for context, msgid in wanted:
			if not translated.get((context, msgid)):
				where = f" (context {context!r})" if context else ""
				print(f"{language}: missing translation for {msgid!r}{where}")
				missing += 1
	print(f"{len(wanted)} strings, {missing} translations missing")
	return 1 if missing else 0


if __name__ == "__main__":
	sys.exit(main())
